import{m as e}from"./index-C860CTCN.js";var t={async getUsers(t){return(await e.get(`/admin/users`,{params:{all:!0,...t}})).data},async getUser(t){return(await e.get(`/admin/users/${t}`)).data},async updateUser(t,n){return(await e.put(`/admin/users/${t}`,n)).data},async toggleStatus(t){return(await e.patch(`/admin/users/${t}/toggle-status`)).data},async deleteUser(t){return(await e.delete(`/admin/users/${t}`)).data}};export{t};